"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/button.css";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import type { ReactNode } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/cn";

export const buttonVariants = cva("whatiuse-button", {
  variants: {
    variant: {
      primary: "whatiuse-button--primary",
      secondary: "whatiuse-button--secondary",
      ghost: "whatiuse-button--ghost",
      quiet: "whatiuse-button--quiet",
    },
    size: {
      small: "whatiuse-button--small",
      medium: "whatiuse-button--medium",
      large: "whatiuse-button--large",
    },
  },
  defaultVariants: {
    variant: "secondary",
    size: "medium",
  },
});

export type ButtonProps = ButtonPrimitive.Props &
  VariantProps<typeof buttonVariants> & {
    loading?: boolean;
    loadingLabel?: ReactNode;
    leadingIcon?: ReactNode;
    trailingIcon?: ReactNode;
  };

export function Button({
  className,
  variant,
  size,
  loading = false,
  loadingLabel,
  leadingIcon,
  trailingIcon,
  disabled,
  focusableWhenDisabled,
  children,
  type = "button",
  ...props
}: ButtonProps) {
  return (
    <ButtonPrimitive
      type={type}
      data-slot="button"
      data-loading={loading || undefined}
      aria-busy={loading || undefined}
      disabled={disabled || loading}
      focusableWhenDisabled={loading || focusableWhenDisabled}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    >
      <span className="whatiuse-button__content">
        {leadingIcon && <span className="whatiuse-button__icon whatiuse-button__icon--leading">{leadingIcon}</span>}
        <span>{children}</span>
        {trailingIcon && <span className="whatiuse-button__icon whatiuse-button__icon--trailing">{trailingIcon}</span>}
      </span>
      <span className="whatiuse-button__loader" aria-hidden="true" data-visible={loading || undefined}>
        <span className="whatiuse-spinner" />
        {loadingLabel && <span className="whatiuse-button__loading-label">{loadingLabel}</span>}
      </span>
    </ButtonPrimitive>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-button { position: relative; display: inline-flex; flex: none; align-items: center; justify-content: center; min-width: 0; border: 1px solid transparent; border-radius: var(--whatiuse-radius-control); white-space: nowrap; cursor: pointer; user-select: none; font-size: 13px; font-weight: 540; letter-spacing: -0.006em; box-shadow: none; transition: color var(--whatiuse-hover-duration), background-color var(--whatiuse-hover-duration), border-color var(--whatiuse-hover-duration), box-shadow var(--whatiuse-hover-duration), transform var(--whatiuse-press-duration) var(--whatiuse-ease-out); }

.whatiuse-button:focus-visible { outline: var(--whatiuse-focus-width) solid var(--whatiuse-focus); outline-offset: var(--whatiuse-focus-offset); }

.whatiuse-button:disabled,
.whatiuse-button[data-disabled] { cursor: not-allowed; opacity: 0.45; }

.whatiuse-button--small { height: var(--whatiuse-control-height-sm); gap: 5px; padding: 0 var(--whatiuse-control-padding-sm); font-size: 12px; }

.whatiuse-button--medium { height: var(--whatiuse-control-height-md); gap: 6px; padding: 0 var(--whatiuse-control-padding-md); }

.whatiuse-button--large { height: var(--whatiuse-control-height-lg); gap: 7px; padding: 0 var(--whatiuse-control-padding-lg); font-size: 14px; }

.whatiuse-button--primary { border-color: var(--whatiuse-inverse); background: var(--whatiuse-inverse); color: var(--whatiuse-on-inverse); box-shadow: 0 1px 1px rgba(0, 0, 0, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.08); }

.whatiuse-button--primary:hover:not(:disabled):not([data-disabled]) { background: var(--whatiuse-inverse-hover); }

.whatiuse-button--secondary { border-color: var(--whatiuse-border); background: var(--whatiuse-control-surface); color: var(--whatiuse-ink); box-shadow: var(--whatiuse-shadow-control); }

.whatiuse-button--secondary:hover:not(:disabled):not([data-disabled]) { border-color: var(--whatiuse-border-strong); background: var(--whatiuse-hover); }

.whatiuse-button--ghost { background: transparent; color: var(--whatiuse-ink-secondary); }

.whatiuse-button--ghost:hover:not(:disabled):not([data-disabled]) { background: var(--whatiuse-hover); color: var(--whatiuse-ink); }

.whatiuse-button--quiet { height: auto; min-height: 24px; padding: 0 2px; border-radius: 3px; background: transparent; color: var(--whatiuse-ink-secondary); }

.whatiuse-button--quiet:hover:not(:disabled):not([data-disabled]) { color: var(--whatiuse-ink); }

@media (pointer: coarse) {
.whatiuse-button--quiet { min-height: var(--whatiuse-control-height-sm); }
}

.whatiuse-button__content { display: inline-flex; align-items: center; justify-content: center; gap: inherit; opacity: 1; transition: opacity 120ms var(--whatiuse-ease-out); }

.whatiuse-button__icon { display: inline-flex; }

.whatiuse-button svg { width: var(--whatiuse-icon-size); height: var(--whatiuse-icon-size); flex: none; transform: translateY(var(--whatiuse-icon-offset-y)); }

.whatiuse-button[data-loading] { opacity: 1; cursor: wait; }

.whatiuse-button[data-loading] .whatiuse-button__content { opacity: 0; }

.whatiuse-button__loader { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; gap: inherit; opacity: 0; pointer-events: none; transition: opacity 120ms var(--whatiuse-ease-out); }

.whatiuse-button__loader[data-visible] { opacity: 1; }

.whatiuse-button__loading-label { line-height: 1; }

.whatiuse-spinner { width: 13px; height: 13px; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: whatiuse-spin 0.75s linear infinite; }

.whatiuse-button:not([data-loading]) .whatiuse-spinner { animation-play-state: paused; }

@media (forced-colors: active) {
.whatiuse-button { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.whatiuse-button--primary { background: Highlight; color: HighlightText; }
}

:root[data-theme="dark"] .whatiuse-button--primary { box-shadow: none; }

.whatiuse-button__icon--trailing svg {
  transform-origin: center;
  transition: transform 160ms var(--whatiuse-ease-out);
}

[data-slot="popover-trigger"][data-popup-open] .whatiuse-button__icon--trailing svg,
[data-slot="menu-trigger"][data-popup-open] .whatiuse-button__icon--trailing svg {
  transform: rotate(180deg);
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-button:active:not(:disabled) { transform: none; }

.whatiuse-button__content,
.whatiuse-button__loader,
.whatiuse-button__icon--trailing svg { transition-duration: 0.01ms; }

.whatiuse-button__content,
.whatiuse-button__loader { transform: none; }

.whatiuse-spinner { animation-duration: 2.4s; }
}

.whatiuse-button .whatiuse-kbd { height: 18px; min-width: 18px; background: color-mix(in oklch, currentColor 7%, transparent); color: currentColor; }

@keyframes whatiuse-spin { to { transform: rotate(360deg); } }
}
